    { const char * tb_v1448 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v1448; }
    { const char * tb_v1449 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1449; }
