    { const char * tb_v2307 = "// ---------- время и дата ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2307; }
    { const char * tb_v2308 = "TB_API long long tb_unix_time(void) { return (long long)time(0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2308; }
    { const char * tb_v2309 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2309; }
    { const char * tb_v2310 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2310; }
    { const char * tb_v2311 = "    struct tm tmv;\n"; *(const char * *)tb_grow(v_lines) = tb_v2311; }
    { const char * tb_v2312 = "    localtime_r(&t, &tmv);\n"; *(const char * *)tb_grow(v_lines) = tb_v2312; }
