    { const char * tb_v2317 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2317; }
    { const char * tb_v2318 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2318; }
    { const char * tb_v2319 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2319; }
    { const char * tb_v2320 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2320; }
    { const char * tb_v2321 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2321; }
    { const char * tb_v2322 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2322; }
    { const char * tb_v2323 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2323; }
    { const char * tb_v2324 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v2324; }
    { const char * tb_v2325 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2325; }
    { const char * tb_v2326 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v2326; }
    { const char * tb_v2327 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2327; }
    { const char * tb_v2328 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2328; }
    { const char * tb_v2329 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v2329; }
    { const char * tb_v2330 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v2330; }
    { const char * tb_v2331 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2331; }
    { const char * tb_v2332 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2332; }
    { const char * tb_v2333 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2333; }
    { const char * tb_v2334 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2334; }
    { const char * tb_v2335 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2335; }
    { const char * tb_v2336 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2336; }
    { const char * tb_v2337 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2337; }
    { const char * tb_v2338 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2338; }
    { const char * tb_v2339 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2339; }
    { const char * tb_v2340 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2340; }
    { const char * tb_v2341 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2341; }
    { const char * tb_v2342 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2342; }
    { const char * tb_v2343 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2343; }
    { const char * tb_v2344 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2344; }
    { const char * tb_v2345 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2345; }
    { const char * tb_v2346 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2346; }
