    { const char * tb_v2566 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v2566; }
    { const char * tb_v2567 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2567; }
    { const char * tb_v2568 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2568; }
    { const char * tb_v2569 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2569; }
    { const char * tb_v2570 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2570; }
    { const char * tb_v2571 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2571; }
    { const char * tb_v2572 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2572; }
    { const char * tb_v2573 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2573; }
    { const char * tb_v2574 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2574; }
    { const char * tb_v2575 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2575; }
    { const char * tb_v2576 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2576; }
    { const char * tb_v2577 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2577; }
    { const char * tb_v2578 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2578; }
    { const char * tb_v2579 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2579; }
    { const char * tb_v2580 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2580; }
    { const char * tb_v2581 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2581; }
    { const char * tb_v2582 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2582; }
    { const char * tb_v2583 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2583; }
    { const char * tb_v2584 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2584; }
    { const char * tb_v2585 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2585; }
    { const char * tb_v2586 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2586; }
    { const char * tb_v2587 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2587; }
