    { const char * tb_v2625 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2625; }
    { const char * tb_v2626 = "        unsigned long long h = tb_hash(d, d->keys->data + at * d->keys->size), i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2626; }
    { const char * tb_v2627 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2627; }
