    { const char * tb_v2631 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2631; }
    { const char * tb_v2632 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2632; }
    { const char * tb_v2633 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2633; }
    { const char * tb_v2634 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2634; }
