    { const char * tb_v2641 = "    const long long *ks = (const long long *)d->keys->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v2641; }
    { const char * tb_v2642 = "    for (long long at = 0; at < d->keys->len; at++) p[ks[at] - d->base] = at + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2642; }
    { const char * tb_v2643 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2643; }
    { const char * tb_v2644 = "    d->pos = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2644; }
