    { const char * tb_v2716 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2716; }
    { const char * tb_v2717 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2717; }
