    { const char * tb_v2761 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
    { const char * tb_v2762 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2762; }
    { const char * tb_v2763 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2763; }
